// TH14 synthetic training alias for native bullet type 8 (RICE), color 0..15.
// Native 0..23 -> modern same number; this is an appearance mapping, not byte-identical art.
const TH14_RICE: int = 480;

// TH14 v1.00b st07bs.ecl.txt BossCard1 (source 953-995), spellEx110 "一鼓「暴れ宮太鼓」".
// Source t0 = the frame after the 120-frame opening buffer; the source 3000-frame timer is cut at SOURCE_LIMIT.
const TIME_LIMIT: int = 3424;
const SOURCE_LIMIT: int = 3000;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 110;

xformdef TAIKO_BURST(target: fx) {
    wait(60); // Source 2835 WAIT a=60
    step_speed(target, 120 + 65536 * EASE_LINEAR); // Source 2841 VELTIME a=120, s keeps current angle
}

// Source 2538 TaikoA01. I0 is passed by value (source child inherits I0 at creation).
async sub taiko(i0: int) {
    set_invuln(65535);
    set_hitbox(16fx);  // Source 2548 setHitbox 32x40 -> circle r=16
    set_hurtbox(16fx); // Source 2549 setHurtbox 32x48 -> r=16
    // Source 2554 moveVel(pi/2 + RANDF2*0.08726646rad, 1.0); +-2.5deg = +-455 BAM.
    var dir: angle = 90deg + (((rand(65536) - 32768) * 910 / 32768) as angle);
    move_vel(0, dir, 1fx, EASE_LINEAR);
    move_vel(120, 90deg, 3fx, EASE_LINEAR); // Source 2555 moveVelTime(120,0,pi/2,3.0)
    if i0 == 0 {
        while $self_y <= 400fx { wait(1); } // Source 2561 FINAL_Y > 400
        taiko_dead();                       // Source 2562 @TaikoDead
        return;                             // Source 2846/2854 TaikoDead2 delete
    }
    loop { wait(1000); } // Source 2566
}

// Source 2823 TaikoDead: six waves of 11-way fan x 5 speed layers, fired on one frame.
sub taiko_dead() {
    var base: int = rand(65536); // Source 2837 RANDRAD; default aimed fan + uniform base == uniform fan
    for batch in 0..6 {          // Source 2838 B=5 -> six etOn
        var target: fx = 1fx + (batch as fx) * 0.6fx; // Source 2836/2842 %A 1.0 then +0.6
        sh_reset(0);
        sh_sprite(0, TH14_RICE, 2);                 // Source 2829 etSprite(0,8,2)
        sh_ring(0, 0);                              // fan; source etAngle base is random anyway
        sh_aim(0, 0);
        sh_count(0, 11, 1);
        sh_angle(0, base as angle, 364 as angle);   // Source 2837 delta 0.034906585rad = 2deg
        sh_xform(0, TAIKO_BURST(target));
        for q in 0..5 {                             // Source 2830 etCount(0,11,5)
            var s: fx = 1fx - (q as fx) * 0.075fx;  // Source 2832 etSpeed 1.0 -> 0.7
            sh_speed(0, s, 0fx);
            sh_dist(0, 0fx - 4fx * s);              // Source 2833 ANIM a=1 retreat -4*speed along angle
            sh_fire(0);
        }
    }
}

// Source 1306 BossCard1_at: ten taikos left->right, wait, ten right->left, repeating.
async sub taiko_waves() {
    loop {
        if $frame >= self_int(1) { return; }
        var i0: int = rand(5) + 2; // Source 1315/1328 I0 = RAND%5+2, decremented per child
        var x: fx = -192fx;
        for i in 0..10 {
            _ = spawn_enemy(x, 0fx, 500, 0, 0, 0, taiko(i0)); // Source 1319 enmCreateA
            x = x + 48fx;
            i0 = i0 - 1;
            wait(5); // Source 1322
        }
        wait(80); // Source 1325
        if $frame >= self_int(1) { return; }
        i0 = rand(5) + 2;
        x = 192fx;
        for j in 0..10 {
            _ = spawn_enemy(x, 0fx, 500, 0, 0, 0, taiko(i0)); // Source 1332
            x = x - 48fx;
            i0 = i0 - 1;
            wait(5); // Source 1335
        }
        wait(140); // Source 1338
    }
}

// Source 412 moveRand(60,0,0.6) with Source 973 moveLimit(0,128,280,64):
// clamp x[-140,140], y[96,160]; direction zones x+-70, y112..144. int0=next step, fx0/1=unit vector.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.6fx * ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768; // signed unit random
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    set_self_int(1, $frame + SOURCE_LIMIT); // source 3000-frame timeout point
    set_self_int(0, 0);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT); // Source 972 movePosTime(60,4,0,144)
    wait(150);                              // Source 975/982 time tags -> t150
    spawn taiko_waves();                    // Source 986 @BossCard1_at async
    wait(180);                              // Source 987
    loop {
        if $frame >= self_int(1) { break; }
        card_move_rand();                   // Source 990 moveRand(60,0,0.6)
        var left: int = self_int(1) - $frame;
        if left > 180 { card_wait(180); }   // Source 991 wait(180)
        else { card_wait(left); break; }
    }
    // Source 970 timeout: cancel the spawner and kill surviving taikos (next-attack staging omitted).
    kill_all_enemies(KILL_SILENT);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // Source Boss 502 setHitbox 48x48 -> r=24
    set_hurtbox(24fx);  // Source Boss 500 setHurtbox 48x48 -> r=24
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 0, 0, 0); // Source 971 spellEx(110,3000,...)
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2100, 0, 0, 0, boss_main); // Source Boss movePos(0,128), lifeSet(2100)
    loop { wait(600); }
}
